using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using ParkingTracker.Domain.Features.Accounts.Aggregates;
using ParkingTracker.Domain.Features.Accounts.ValueObjects;

namespace ParkingTracker.Persistence.EntityFrameworkCore.Features.Accounts;

/// <summary>
/// Author      : Gihed Annabi
/// Date        : 11-2026
/// Purpose     : Maps <see cref="UserAccount"/> to <c>user_accounts</c> and its <see cref="DeviceSession"/> children to
///              <c>device_sessions</c>. Keys are never generated by the database, because the aggregate chooses them; a new session
///              of a loaded account is therefore inserted and not mistaken for an existing row. Days are <c>date</c>, instants
///              <c>timestamptz</c>. A rotation and a revocation are guarded by concurrency tokens on the session row, so two requests
///              that present the same refresh token cannot both rotate it: the second save fails with a concurrency error.
/// </summary>
internal sealed class UserAccountConfiguration : IEntityTypeConfiguration<UserAccount>, IEntityTypeConfiguration<DeviceSession>
{
	#region Constants
	/// <summary>
	/// The length of a hash written in hexadecimal.
	/// </summary>
	private const int HashLength = 64;
	#endregion

	#region Configuration
	/// <inheritdoc />
	public void Configure(EntityTypeBuilder<UserAccount> builder)
	{
		ArgumentNullException.ThrowIfNull(builder);
		builder.ToTable("user_accounts");
		builder.HasKey(account => account.Id);
		builder.Property(account => account.Id).HasConversion(id => id.Value, value => new UserAccountId(value)).ValueGeneratedNever();
		builder.Property(account => account.SubjectHash)
			.HasConversion(hash => hash.Value, text => SubjectHash.Create(text).Value)
			.HasColumnType("text")
			.HasMaxLength(HashLength);
		builder.HasIndex(account => account.SubjectHash).IsUnique();
		builder.Property(account => account.CreatedOn).HasColumnType("date");
		builder.Property(account => account.LastSeenOn).HasColumnType("date");
		builder.Property(account => account.Version).IsConcurrencyToken();
		builder.HasMany(account => account.Sessions).WithOne().HasForeignKey("AccountId").IsRequired().OnDelete(DeleteBehavior.Cascade);
		builder.Navigation(account => account.Sessions).UsePropertyAccessMode(PropertyAccessMode.Field);
	}

	/// <inheritdoc />
	public void Configure(EntityTypeBuilder<DeviceSession> builder)
	{
		ArgumentNullException.ThrowIfNull(builder);
		builder.ToTable("device_sessions");
		builder.HasKey(session => session.Id);
		builder.Property(session => session.Id).HasConversion(id => id.Value, value => new DeviceSessionId(value)).ValueGeneratedNever();
		builder.Property(session => session.TokenHash)
			.HasConversion(hash => hash.Value, text => RefreshTokenHash.Create(text).Value)
			.HasColumnType("text")
			.HasMaxLength(HashLength);
		builder.HasIndex(session => session.TokenHash).IsUnique();
		builder.HasIndex(session => session.FamilyId);
		builder.Property(session => session.LastUsedOn).HasColumnType("date");
		builder.Property(session => session.AbsoluteExpiryUtc).HasColumnType("timestamp with time zone");
		builder.Property(session => session.RotatedOn).HasColumnType("timestamp with time zone").IsConcurrencyToken();
		builder.Property(session => session.Revoked).IsConcurrencyToken();
	}
	#endregion
}
